SELECT c.customer_id, SUM(i.total) AS billings, SUM(rr.amount) AS recognized_revenue FROM customer_contract c LEFT JOIN invoice i ON i.contract_id=c.id AND i.generation_run_id IN (:actual_run_id,:generation_run_id) LEFT JOIN performance_obligation po ON po.contract_id=c.id AND po.generation_run_id IN (:actual_run_id,:generation_run_id) LEFT JOIN revenue_recognition rr ON rr.performance_obligation_id=po.id AND rr.generation_run_id IN (:actual_run_id,:generation_run_id) WHERE c.generation_run_id IN (:actual_run_id,:generation_run_id) GROUP BY c.customer_id;
